import sys
from fractions import Fraction

def expected_tosses(n):
    if n == 1:
        return Fraction(1, 1)
    k = 1
    while 2**k < n:
        k += 1
    if 2**k == n:
        return Fraction(k)
    else:
        p = Fraction(2**(k-1), n)
        return p * expected_tosses(2**(k-1)) + (1 - p) * expected_tosses(n - 2**(k-1)) + 1

n = int(sys.stdin.read().strip())
result = expected_tosses(n)
print(f"{result.numerator}/{result.denominator}")
